const jobId = $("01 Input Trigger").item.json.jobId || ($json && $json.job_id);
const row = ($json && $json.job_id) ? $json : null;
let errorCode = null;
let errorMessage = null;
if (!row) {
  errorCode = "JOB_NOT_FOUND";
  errorMessage = "No content_jobs row found for jobId " + jobId + ".";
}
return {
  jobId,
  job: row,
  ok: errorCode === null,
  errorCode,
  errorMessage,
};

const j = $json || {};
const code = j.errorCode || "UNKNOWN_ERROR";
const message = j.errorMessage || "An unknown error occurred while retrieving job status.";
const jobId = j.jobId || null;
return {
  success: false,
  jobId,
  status: "FAILED",
  message,
  data: null,
  warnings: [],
  errors: [{ code, language: null, path: null, message }],
  nextAllowedActions: []
};
